import { auth } from "../firebase.js";

/**
 * Ensures Firebase Auth state is initialized and returns the authenticated user if present.
 * Uses a safe non-blocking timeout (max 1500ms) to guarantee the call never hangs indefinitely.
 */
export async function getAuthenticatedFirebaseUser(): Promise<typeof auth.currentUser> {
  if (auth?.currentUser) {
    return auth.currentUser;
  }
  if (typeof auth?.authStateReady === "function") {
    try {
      await Promise.race([
        auth.authStateReady(),
        new Promise((resolve) => setTimeout(resolve, 1500))
      ]);
    } catch (err) {
      console.warn("[apiUtils] authStateReady wait warning:", err);
    }
  }
  return auth?.currentUser || null;
}

/**
 * Retrieves a fresh, valid Firebase ID Token directly from the client session.
 * If forceRefresh is true, forcibly requests a new token from Google identity backend.
 */
export async function getFreshAuthToken(forceRefresh = false): Promise<string | null> {
  const user = await getAuthenticatedFirebaseUser();
  if (user) {
    try {
      const tokenPromise = user.getIdToken(forceRefresh);
      const token = await Promise.race([
        tokenPromise,
        new Promise<null>((resolve) => setTimeout(() => resolve(null), 2500))
      ]);
      if (token) return token;
    } catch (err) {
      console.warn("[getFreshAuthToken] Failed to retrieve Firebase ID token:", err);
    }
  }

  if (typeof window !== "undefined") {
    const localToken = localStorage.getItem("zakir_auth_token");
    if (localToken && (localToken.startsWith("ey") || localToken.startsWith("sec_") || localToken.startsWith("mock_token_"))) {
      return localToken;
    }
  }

  return null;
}

/**
 * Helper to sanitize environment base URLs, stripping markdown links like [url](url) or extra brackets.
 */
export function sanitizeBaseUrl(rawUrl?: string): string {
  if (!rawUrl || typeof rawUrl !== "string") return "";
  let trimmed = rawUrl.trim();
  
  // Extract clean URL if markdown link syntax like [https://getzakir.com](https://getzakir.com) was passed
  const markdownMatch = trimmed.match(/\[.*?\]\((https?:\/\/[^\)]+)\)/i);
  if (markdownMatch && markdownMatch[1]) {
    trimmed = markdownMatch[1].trim();
  } else {
    // Remove brackets, parentheses, or double quotes
    trimmed = trimmed.replace(/[\[\]\(\)'"]/g, "").trim();
  }

  if (!/^https?:\/\//i.test(trimmed)) {
    return "";
  }

  return trimmed.replace(/\/+$/, "");
}

/**
 * Helper to ensure endpoint URL formatted with correct origin or relative path.
 */
function resolveEndpointUrl(url: string): string {
  if (url.startsWith("http://") || url.startsWith("https://")) {
    return url;
  }
  const formattedEndpoint = url.startsWith('/') ? url : `/${url}`;
  
  if (typeof window !== "undefined") {
    // When running in a standard web browser (http/https), ALWAYS use same-origin relative endpoints.
    // This strictly prevents www.getzakir.com -> getzakir.com redirects, Render spin-down delays, and cross-origin CORS errors.
    const isWeb = window.location.protocol === "http:" || window.location.protocol === "https:";
    if (isWeb) {
      return formattedEndpoint;
    }

    let rawBase = "";
    try {
      const metaEnv = (new Function("return import.meta.env")()) || {};
      rawBase = metaEnv.VITE_API_BASE_URL || metaEnv.VITE_BACKEND_URL || "";
    } catch {
      rawBase = "";
    }
    const cleanBase = sanitizeBaseUrl(rawBase);
    
    if (cleanBase) {
      try {
        const currentOrigin = window.location.origin.replace(/\/$/, '');
        const currentHost = window.location.hostname.toLowerCase();
        const baseHost = new URL(cleanBase).hostname.toLowerCase();

        // Standardize domain roots so getzakir.com and www.getzakir.com match seamlessly
        const currentDomainRoot = currentHost.replace(/^www\./, '');
        const baseDomainRoot = baseHost.replace(/^www\./, '');

        if (currentHost === baseHost || currentOrigin === cleanBase || currentDomainRoot === baseDomainRoot) {
          return formattedEndpoint;
        }
        return `${cleanBase}${formattedEndpoint}`;
      } catch (e) {
        return formattedEndpoint;
      }
    }
  }
  return formattedEndpoint;
}

/**
 * Standardized authenticated fetch helper that automatically retrieves
 * the current Firebase ID Token or local session token, attaches it in the Authorization header,
 * and seamlessly performs token refresh & retry on 401 errors.
 */
export async function authenticatedFetch(
  url: string,
  options: RequestInit = {}
): Promise<Response> {
  const headers = new Headers(options.headers || {});
  let token: string | null = null;

  const user = await getAuthenticatedFirebaseUser();
  if (user) {
    try {
      token = await user.getIdToken(false);
    } catch (err) {
      console.warn("[authenticatedFetch] Failed to retrieve Firebase auth token:", err);
    }
  }

  if (!token && typeof window !== "undefined") {
    const localToken = localStorage.getItem("zakir_auth_token");
    if (localToken && (localToken.startsWith("ey") || localToken.startsWith("sec_") || localToken.startsWith("mock_token_"))) {
      token = localToken;
    }
  }

  if (token && !headers.has("Authorization")) {
    headers.set("Authorization", `Bearer ${token}`);
  }

  const targetUrl = resolveEndpointUrl(url);

  const executeFetch = async (retryCount = 0): Promise<Response> => {
    let controller: AbortController | null = null;
    let timeoutId: any = null;
    let effectiveSignal = options.signal;

    if (!effectiveSignal && typeof AbortController !== "undefined") {
      controller = new AbortController();
      effectiveSignal = controller.signal;
      timeoutId = setTimeout(() => {
        if (controller) {
          controller.abort(new Error("Request timed out after 15 seconds"));
        }
      }, 15000);
    }

    try {
      const response = await fetch(targetUrl, {
        credentials: "include",
        ...options,
        headers,
        signal: effectiveSignal
      });

      if (timeoutId) clearTimeout(timeoutId);

      // Handle 401: If token expired, refresh token once and retry request
      if (response.status === 401 && user && retryCount === 0) {
        try {
          console.info("[authenticatedFetch] 401 Unauthorized received. Refreshing Firebase ID Token and retrying once...");
          const freshToken = await user.getIdToken(true);
          if (freshToken) {
            headers.set("Authorization", `Bearer ${freshToken}`);
            return await fetch(targetUrl, {
              credentials: "include",
              ...options,
              headers
            });
          }
        } catch (retryErr) {
          console.warn("[authenticatedFetch] Single retry with fresh token failed:", retryErr);
        }
      }

      return response;
    } catch (netErr: any) {
      if (timeoutId) clearTimeout(timeoutId);

      const isTimeout = netErr?.name === "AbortError" || (netErr?.message && netErr.message.includes("timed out"));

      // Retry once on transient network error (e.g. initial server boot/reconnect) - do not retry if explicitly timed out
      if (!isTimeout && retryCount < 1) {
        console.warn(`[authenticatedFetch] Transient network warning for ${targetUrl}, retrying once in 300ms...`);
        await new Promise((resolve) => setTimeout(resolve, 300));
        return executeFetch(retryCount + 1);
      }

      console.warn(`[authenticatedFetch] Network error for ${targetUrl}:`, netErr?.message || netErr);
      const errorMsg = isTimeout
        ? "استغرقت الاستجابة وقتاً أطول من المتوقع (انتهت مهلة الطلب). يرجى المحاولة مرة أخرى."
        : (netErr?.message || "فشل الاتصال بالخادم. يرجى التحقق من اتصال الإنترنت والمحاولة مجدداً.");

      return new Response(
        JSON.stringify({
          success: false,
          code: isTimeout ? "GATEWAY_TIMEOUT" : "NETWORK_ERROR",
          error: errorMsg,
          userFriendlyMessage: errorMsg
        }),
        {
          status: isTimeout ? 504 : 503,
          headers: { "Content-Type": "application/json" }
        }
      );
    }
  };

  return executeFetch(0);
}

/**
 * Returns an object containing the Authorization Bearer header if a user is logged in.
 */
export async function getAuthHeader(forceRefresh = false): Promise<Record<string, string>> {
  const token = await getFreshAuthToken(forceRefresh);
  return token ? { Authorization: `Bearer ${token}` } : {};
}

/**
 * Safely parse JSON from a Response object, guarding against empty bodies,
 * truncated streams, HTML gateway error pages, and network dropouts.
 */
export async function safeJsonResponse<T = any>(
  response: Response,
  fallbackMessage?: string
): Promise<T> {
  let text = "";
  try {
    text = await response.text();
  } catch (readErr) {
    console.warn("[safeJsonResponse] Failed to read response body:", readErr);
  }

  const trimmed = (text || "").trim();

  // If the body is completely empty
  if (!trimmed) {
    if (!response.ok) {
      const defaultStatusMsg =
        response.status === 401
          ? "غير مصرح أو الجلسة غير صالحة."
          : response.status === 403
          ? "ليس لديك صلاحية لتنفيذ هذا الإجراء."
          : response.status === 404
          ? "الخدمة أو المسار المطلوب غير متوفر حالياً."
          : response.status === 429
          ? "تم تجاوز عدد المحاولات المسموح بها مؤقتاً."
          : response.status >= 500
          ? "تعذر إتمام الطلب من الخادم حالياً."
          : "تعذر إتمام الإجراء المطلوب.";

      const statusErrCode =
        response.status === 401
          ? "UNAUTHORIZED"
          : response.status === 403
          ? "FORBIDDEN"
          : response.status === 429
          ? "TOO_MANY_REQUESTS"
          : response.status >= 500
          ? "SERVER_ERROR"
          : `HTTP_${response.status}`;

      return {
        success: false,
        statusCode: response.status,
        code: statusErrCode,
        error: fallbackMessage || defaultStatusMsg,
        userFriendlyMessage: fallbackMessage || defaultStatusMsg
      } as unknown as T;
    }
    return { success: true, statusCode: response.status } as unknown as T;
  }

  // If the response is HTML error from Vite, Nginx, or Cloud Run gateway
  if (
    trimmed.startsWith("<!DOCTYPE") ||
    trimmed.startsWith("<html") ||
    trimmed.startsWith("<head")
  ) {
    const htmlMsg =
      fallbackMessage ||
      (response.status >= 500
        ? "الخادم قيد التحديث أو إعادة التشغيل حالياً. يرجى المحاولة بعد لحظات."
        : "استجابة غير متوقعة من بوابة الخادم. يرجى إعادة المحاولة.");
    return {
      success: false,
      statusCode: response.status,
      code: response.status >= 500 ? "SERVER_ERROR" : "GATEWAY_HTML_RESPONSE",
      error: htmlMsg,
      userFriendlyMessage: htmlMsg
    } as unknown as T;
  }

  try {
    const parsed = JSON.parse(trimmed);
    if (parsed && typeof parsed === "object") {
      if (!("statusCode" in parsed)) {
        parsed.statusCode = response.status;
      }
      if (!response.ok && !parsed.code && !parsed.error) {
        parsed.code = `HTTP_${response.status}`;
      }
    }
    return parsed as T;
  } catch (parseErr) {
    console.warn("[safeJsonResponse] JSON parse exception:", parseErr, "Body sample:", trimmed.substring(0, 100));
    const parseMsg = fallbackMessage || "حدث خطأ أثناء معالجة بيانات الخادم. يرجى المحاولة لاحقاً.";
    return {
      success: false,
      statusCode: response.status,
      code: "INVALID_JSON_RESPONSE",
      error: parseMsg,
      userFriendlyMessage: parseMsg
    } as unknown as T;
  }
}
